// fix-expo-font-paths.js

const fs = require("fs")
const path = require("path")

/**
 * Entry JS bundle directory generated by:
 * npx expo export --platform web
 *
 * This is where Expo Web injects runtime asset references,
 * including @expo/vector-icons font paths.
 */
const ENTRY_DIR = path.join(
  process.cwd(),
  "dist",
  "_expo",
  "static",
  "js",
  "web"
)

/**
 * Target directory where we expect rewritten font assets.
 * These fonts must be copied manually during build step.
 */
const FONT_RELATIVE_PATH = "fonts/";

const FONTS_DIR = path.join(
  process.cwd(),
  "dist",
  "fonts"
)

/**
 * Regex matching Expo Web generated font URLs.
 * These point into node_modules at runtime, which breaks on static hosts.
 *
 * Example matched path:
 * /assets/node_modules/@expo/vector-icons/.../Fonts/FontAwesome5.ttf
 */
const EXPO_FONT_REGEX =
  /\/assets\/node_modules\/@expo\/vector-icons\/build\/vendor\/react-native-vector-icons\/Fonts\/(FontAwesome[^"')]+\.ttf)/g

/**
 * Simple logger wrapper for build-time visibility.
 * Keeps output consistent and searchable in CI logs.
 */
function log(msg) {
  console.log(`[expo-font-fix] ${msg}`)
}

/**
 * Collect all entry-*.js files generated by Expo Web bundler.
 * These contain the runtime asset references we need to patch.
 */
function getEntryFiles() {
  const files = fs.readdirSync(ENTRY_DIR)

  return files
    .filter((f) => f.startsWith("entry-") && f.endsWith(".js"))
    .map((f) => path.join(ENTRY_DIR, f))
}

/**
 * Patches a single JS bundle file:
 * - finds Expo vector icon font URLs
 * - rewrites them to local static assets path
 *
 * This avoids Netlify / static host rewrite issues.
 */
function patchFile(filePath) {
  const original = fs.readFileSync(filePath, "utf8")

  const matches = [...original.matchAll(EXPO_FONT_REGEX)]

  // No font references in this bundle file
  if (matches.length === 0) {
    log(`no fonts found in ${path.basename(filePath)}`)
    return
  }

  log(`found ${matches.length} font refs in ${path.basename(filePath)}`)

  let patched = original

  for (const m of matches) {
    const fullMatch = m[0]     // full URL match
    const fileName = m[1]      // extracted font filename

    log(`replacing font: ${fullMatch}`)

    // Replace Expo internal node_modules path with stable static path
    patched = patched.replace(
      fullMatch,
      `${FONT_RELATIVE_PATH}${fileName}`
    )

    log(`with ${FONT_RELATIVE_PATH}${fileName}`)
  }

  // Write file only if changes occurred (avoid unnecessary FS writes)
  if (patched !== original) {
    fs.writeFileSync(filePath, patched, "utf8")
    log(`patched file written: ${path.basename(filePath)}`)
  } else {
    log(`no changes written: ${path.basename(filePath)}`)
  }
}

/**
 * Extract all expected font filenames from bundles.
 * Used for post-check validation step.
 */
function collectExpectedFontsFromBundles(files) {
  const set = new Set()

  for (const file of files) {
    const content = fs.readFileSync(file, "utf8")

    const matches = [...content.matchAll(EXPO_FONT_REGEX)]

    for (const m of matches) {
      set.add(m[1])
    }
  }

  return [...set]
}

/**
 * Validates whether all referenced fonts exist in output directory.
 *
 * This does NOT fix missing files — only warns.
 * Missing fonts mean broken icon rendering at runtime.
 */
function checkFonts(expectedFonts) {
  if (!fs.existsSync(FONTS_DIR)) {
    log(`WARNING: Fonts directory missing: ${FONTS_DIR}`)
    log(`Create directory and copy fonts before deployment`)
    return
  }

  const existing = fs.readdirSync(FONTS_DIR)
  log(existing);
  const missing = expectedFonts.filter(
    (f) => !existing.includes(f)
  )

  if (missing.length === 0) {
    log(`all fonts present in ${FONT_RELATIVE_PATH}`)
    return
  }

  log(`WARNING: missing ${missing.length} fonts`)

  // List missing assets for manual intervention
  for (const f of missing) {
    log(`missing font: ${f}`)
  }

  log(`required action: copy missing fonts into dist/assets/Fonts`)
}

/**
 * Main execution pipeline:
 * 1. Validate build output structure
 * 2. Patch JS bundles
 * 3. Extract expected font references
 * 4. Validate physical font assets
 */
function run() {
  log("starting postbuild font patch")

  // Guard: ensure Expo build output exists
  if (!fs.existsSync(ENTRY_DIR)) {
    throw new Error(`Entry dir not found: ${ENTRY_DIR}`)
  }

  const files = getEntryFiles()
  log(`found ${files.length} entry files`)

    // Collect expected fonts after patching logic
    const expectedFonts = collectExpectedFontsFromBundles(files)
    log(`expected fonts detected: ${expectedFonts.length}`)

  // Patch each bundle file independently
  for (const file of files) {
    patchFile(file)
  }



  // Validate filesystem consistency
  checkFonts(expectedFonts)

  log("finished")
}

run()